"""Dependency-free static, privacy-safe public dashboard builder."""
import json, html
from pathlib import Path
D=json.loads(Path('data/evidence.json').read_text())
e=html.escape
nav=[('index','Executive summary')]+[(p['id'],p['title']) for p in D['pages']]+[('sources','Sources & methodology')]
def shell(id,title,content):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Privacy-safe, evidence-linked Los Angeles net lease property research. Unknown financial values are withheld."><title>{e(title)} · Jack / Property research</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="mark">J.</span> JACK<span class="brand-sub">PROPERTY INTELLIGENCE</span></a><div class="nav-label">RESEARCH WORKSPACE</div><nav>{''.join(f'<a {"aria-current=page" if key==id else ""} href="{key}.html"><span>{str(i+1).zfill(2)}</span>{e(label)}</a>' for i,(key,label) in enumerate(nav))}</nav><div class="privacy"><span>◈</span><b>Privacy by design</b><p>Asset A · anonymized<br>No owner or parcel identifiers</p></div></aside><div class="workspace"><header><span>RESEARCH / LOS ANGELES</span><span class="stamp">● &nbsp; Evidence review · 07 Nov 2026</span></header><main id="main">{content}</main><footer>Independent decision-support research. Not an appraisal, legal opinion or personalized financial advice.<br>Static evidence snapshot · No tracking, forms, third-party assets or private documents · <a href="sources.html">Methodology & limitations</a></footer></div></body></html>'''
def table(p):
    heads=p['columns']+['Evidence','Official source']
    out='<div class="table-wrap"><table><caption>'+e(p['title'])+' · evidence register</caption><thead><tr>'+''.join('<th scope="col">'+e(c)+'</th>' for c in heads)+'</tr></thead><tbody>'
    for r in p['rows']:
        s=D['sources'][r['source']]; status=r['status']; cls='verified' if status=='Verified' else 'analysis' if status=='Analysis' else 'unknown'
        out+='<tr>'+''.join('<td'+(' class="empty" aria-label="Unverified value; intentionally blank"' if c=='' else '')+'>'+e(c)+'</td>' for c in r['cells'])+f'<td><span class="badge {cls}">{e(status)}</span></td><td><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["label"])} ↗</a></td></tr>'
    return out+'</tbody></table></div>'
for p in D['pages']:
    intro=f'<div class="eyebrow">{e(p["kicker"])}</div><h1>{e(p["title"])}</h1><p class="lede">{e(p["description"])}</p><div class="legend"><span class="badge verified">Verified</span> Source-matched observation <span class="badge analysis">Analysis</span> Conditional interpretation <span class="badge unknown">Unverified</span> Missing evidence</div>'
    Path(p['id']+'.html').write_text(shell(p['id'],p['title'],intro+table(p)))
content='''<div class="eyebrow">ASSET A / NET LEASE DECISION BRIEF</div><h1>Protect the income.<br><span>Preserve your options.</span></h1><p class="lede">A source-linked assessment of a Jack in the Box net-leased property in the Los Angeles area. Built to separate what we know from what we cannot yet verify.</p><div class="hero-note"><span class="badge analysis">CONDITIONAL STRATEGY</span><h2>Evaluate an early renewal and a sale in parallel.</h2><p>Maintain optionality under the current lease while assessing documented renewal terms against verified after-tax sale proceeds. Do not authorize an irreversible decision on regional averages alone.</p><a class="button" href="decisions.html">Explore decision pathways <span>→</span></a><a class="quiet" href="review.html">See the evidence gaps ↗</a><a class="quiet" href="analysis/index.html">Deep-dive evidence dashboard →</a></div><div class="section-heading"><h2>The investment picture</h2><span>Regional context ≠ property forecast</span></div><div class="cards"><article><div class="eyebrow">DEMAND / LA CITY</div><strong>−0.8%</strong><p>Population change, April 2020 estimates base to July 2025. A headwind, not a local sales forecast.</p><a href="https://www.census.gov/quickfacts/losangelescitycalifornia">Census · V2025 ↗</a></article><article><div class="eyebrow">JOBS / LA METRO</div><strong>+0.5%</strong><p>Nonfarm employment year-over-year, September 2026. Not seasonally adjusted; subject to revision.</p><a href="https://www.bls.gov/regions/west/summary/blssummary_losangeles.pdf">BLS · November 2026 summary ↗</a></article><article><div class="eyebrow">TENANT / CHAIN-WIDE</div><strong>−1.1%</strong><p>System same-store sales, Q3 FY2026. This is not the subject restaurant’s performance.</p><a href="tenant.html">Issuer evidence & lease gaps ↗</a></article></div><section class="split"><div><div class="eyebrow">EXECUTIVE SUMMARY</div><h2>Income durability first.<br>Growth second.</h2><p>The regional evidence is mixed: employment is growing modestly, population is below its 2020 estimates base, and the chain reports weaker same-store sales. These indicators justify diligence, not a categorical sell decision.</p><p>For wealth preservation, assess enforceable rent, tenant credit, owner liquidity, after-tax alternatives and uninsured downside together. An extension may protect income; a sale may reduce concentration. Neither is demonstrably superior with the current evidence.</p></div><div class="callout"><h3>What this report cannot establish</h3><p>The reported expiration range of 2030–2035 and NNN description are unverified user context. Exact term, notice dates, guaranty, rent, debt and property identity are unavailable.</p><p><b>No price target, cap rate, renewal probability or personal risk score is published.</b> Unsupported numerical fields remain blank.</p><a href="model.html">View the evidence-gated framework →</a></div></section><div class="section-heading"><h2>Follow the evidence</h2><span>Public facts. Clear limitations.</span></div><div class="route-grid"><a href="economy.html"><b>01 / Area fundamentals</b><p>Population, income, jobs and purchasing power.</p>Read the evidence →</a><a href="risk.html"><b>03 / Risk & resilience</b><p>Earthquake, wildfire, flood and income disruption.</p>Review downside →</a><a href="review.html"><b>07 / Flagged for Review</b><p>Missing documents, geographic gaps and uncertainty.</p>Inspect limitations →</a></div>'''
content += '<p style="margin-top:18px;padding:12px 16px;border:1px solid #d9c26a;background:#fffbe8;border-radius:10px"><strong>Companion deep-dives:</strong> <a href="docs/index.html">verified research &amp; tables (docs/)</a> · <a href="analysis/index.html">data-backed deep-dive dashboard (analysis/)</a> · <a href="brief/index.html">interactive sell-vs-renew brief, risk register &amp; scenario model (brief/)</a> · <a href="pages/index.html">full sourced dashboard (pages/)</a> · <a href="decision-file/index.html">verified decision file (decision-file/)</a></p>'
Path('index.html').write_text(shell('index','Executive summary',content))
src={'title':'Official source register','columns':['Publisher / document','Type','Reviewed','Use and limits'],'rows':[dict(cells=[s['label'],s['type'],s['checked'],'Source inspected for its limited use; CDE unavailable on this audit. Links do not verify property inputs or endorse analysis.'],status=('Needs review' if k=='school' else 'Verified'),source=k) for k,s in D['sources'].items()]}
content='''<div class="eyebrow">08 / AUDIT TRAIL</div><h1>Sources & methodology</h1><p class="lede">Evidence first. Interpretation second. Unknowns stay unknown.</p><section class="callout"><h2>Verification standard</h2><p>Each Verified row was manually matched to the linked government publication or issuer release on 7 November 2026 (except the unavailable CDE route). Verified means the source reports the observation—not that it predicts this property. Issuer reports are labeled separately from government data.</p><p>Analysis rows are our conditional reasoning. Their official links support background context only; they do not endorse the recommendation. Unverified rows contain no invented value; links are research routes or explicitly limited context, not proof of missing facts.</p><p>QuickFacts observations use different vintages, geography and survey periods. ACS estimates have sampling error; no tract estimates or margins of error were obtained. The BLS November 4, 2026 summary uses unadjusted data and may be revised. No model has been trained or back-tested; no causal claim about property value is made.</p><h3>Privacy and publication boundary</h3><p>Asset A and Owner A are placeholders. No addresses, parcel IDs, owner names, contact details, financial accounts or private lease records are collected or published. No analytics, third-party embeds or external scripts are used. GitHub hosting may retain standard access logs. Public source links open their publishers’ websites.</p><h3>Reproducibility and maintenance</h3><p>Public evidence is stored in data/evidence.json; scripts/build.py generates every page. scripts/validate.py checks table provenance, local links and blank-value status. Source values were reviewed manually; automated validation does not assert live external availability or semantic verification. This is a fixed snapshot, not a live data feed. Refresh official releases and reassess geographic fit before acting.</p><p>Initial repository review found only a README and no historical analysis or personal data. No hidden property records or private evidence were inferred. Missing private documents cannot be supplied through autonomous public research.</p></section>'''+table(src)
Path('sources.html').write_text(shell('sources','Sources & methodology',content))

# Apply evidence boundaries to both root and preserved companion layers.
from audit_publication import apply
apply()
